def find_non_grid_values(grid, grid_line_val):
    n = len(grid)
    # Find grid line positions
    row_lines, col_lines = [], []
    for r in range(n):
        if all(grid[r][c] == grid_line_val for c in range(n)):
            row_lines.append(r)
    for c in range(n):
        if all(grid[r][c] == grid_line_val for r in range(n)):
            col_lines.append(c)

    # Get interior cells (not on grid lines)
    for r in range(n):
        for c in range(n):
            if r not in row_lines and c not in col_lines and grid[r][c] != grid_line_val:
                yield (r, c, grid[r][c])

